public class InnerCampaignDataPartitionStorageOptionsFactory(Action<Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions> factoryAction = null) : SubResourceFactory<Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions>
{

    internal InnerCampaignStorageMaximumSizeFactory MaximumSizeFactory { get; set; }

    internal InnerCampaignStorageMinimumTimeToLiveFactory MinimumTimeToLiveFactory { get; set; }

    protected override Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions Create()
    {
        var dataPartitionStorageOptionsResult = CreateDataPartitionStorageOptions();
        factoryAction?.Invoke(dataPartitionStorageOptionsResult);

        return dataPartitionStorageOptionsResult;
    }

    private Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions CreateDataPartitionStorageOptions()
    {
        var dataPartitionStorageOptionsResult = new Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions();

        return dataPartitionStorageOptionsResult;
    }
    public override void CreateChildren(Humidifier.IoTFleetWise.CampaignTypes.DataPartitionStorageOptions result)
    {
        base.CreateChildren(result);

        result.MaximumSize ??= MaximumSizeFactory?.Build();
        result.MinimumTimeToLive ??= MinimumTimeToLiveFactory?.Build();
    }

} // End Of Class

